    private LinearLayout entry(String icon,String name,String description,int color,Runnable action){LinearLayout box=k.card(color);box.setPadding(k.dp(14),k.dp(14),k.dp(14),k.dp(12));LinearLayout top=k.row();UiKit.Icon glyph=new UiKit.Icon(a,icon,k.ink);glyph.setPadding(k.dp(7),k.dp(7),k.dp(7),k.dp(7));glyph.setBackground(k.shape(0x88FFFFFF,13));top.addView(glyph,new LinearLayout.LayoutParams(k.dp(36),k.dp(36)));top.addView(new View(a),new LinearLayout.LayoutParams(0,1,1));top.addView(new UiKit.Icon(a,"arrow",k.ink),new LinearLayout.LayoutParams(k.dp(20),k.dp(20)));box.addView(top);k.gap(box,9);box.addView(k.heading(name,17));TextView desc=k.text(description,11,k.ink);desc.setPadding(0,k.dp(5),0,0);box.addView(desc);TextView status=k.text(icon.equals("bell")?"关键词与同音提醒":"警示声音与口头警示",10,k.ink);status.setPadding(0,k.dp(9),0,0);box.addView(status);box.setOnClickListener(v->action.run());box.setFocusable(true);box.setContentDescription(name+"，"+description);k.press(box);return box;}

    private void header(){
        if(badge.getParent() instanceof ViewGroup)((ViewGroup)badge.getParent()).removeView(badge);
        header.removeAllViews();header.setPadding(k.dp(12),0,k.dp(8),0);
        backButton=k.iconButton("back","返回",this::goBack);backButton.setVisibility(isPrimary(route)?View.GONE:View.VISIBLE);header.addView(backButton);
        if(isPrimary(route)){UiKit.Icon brand=new UiKit.Icon(a,"wave",k.ink);brand.setBackground(k.shape(k.coral,9));brand.setPadding(k.dp(4),k.dp(4),k.dp(4),k.dp(4));header.addView(brand,new LinearLayout.LayoutParams(k.dp(26),k.dp(26)));}
        String name=route.equals("archives")?"对话档案":isPrimary(route)?"声应":route.equals("communication")?"即时沟通":route.equals("daily")?"日常音提醒":route.equals("danger")?"危险音提醒":route.equals("emotions")?"情绪记录本":route.equals("notifications")?"通知":route.equals("device")?"我的录音豆":route.equals("voice")?(voiceKind.equals("mine")?"我的语音包":"其他语音包"):route.equals("editor")?"重要标记":"对话详情";
        TextView title=k.heading(name,route.equals("archives")?19:isPrimary(route)?23:17);title.setSingleLine(true);title.setEllipsize(TextUtils.TruncateAt.END);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.leftMargin=k.dp(8);header.addView(title,tp);
        if(route.equals("archives")){header.addView(k.iconButton("search","搜索对话内容或日期",()->{search.setVisibility(search.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);if(search.getVisibility()==View.VISIBLE)search.requestFocus();}));View filterButton=k.iconButton("filter","筛选对话",this::filterDialog);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(k.dp(48),k.dp(48));fp.leftMargin=k.dp(8);header.addView(filterButton,fp);}
        FrameLayout bell=new FrameLayout(a);bell.setMinimumWidth(k.dp(48));View button=k.iconButton("bell","查看通知",()->show("notifications",true));bell.addView(button,new FrameLayout.LayoutParams(k.dp(48),k.dp(48)));badge.setBackground(k.shape(k.coral,12));badge.setPadding(k.dp(4),0,k.dp(4),0);FrameLayout.LayoutParams count=new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.RIGHT);count.topMargin=k.dp(3);bell.addView(badge,count);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(k.dp(48),k.dp(48));bp.leftMargin=k.dp(8);header.addView(bell,bp);updateBadge();
    }

    private boolean isPrimary(String r){return Arrays.asList("home","archives","marks","mine").contains(r);}
    void show(String next,boolean push){
        if(noteDialog!=null){noteDialog.dismiss();noteDialog=null;}if(recorder!=null&&!next.equals("voice"))finishRecording();
        if(next.equals("device")&&!pages.containsKey("device")){LinearLayout device=page("device");title(device,"我的录音豆","连接设备后，使用录音豆实体键控制录音。");device.addView(k.copy("录音豆编号（可留空扫描后选择）"));move(a.targetInput,device);k.style(a.targetInput);move(a.status,device);k.style(a.status);Button permission=k.button("连接准备与蓝牙授权",true);permission.setOnClickListener(v->a.permissions());device.addView(permission);Button scan=k.button("查找我的录音豆",false);scan.setOnClickListener(v->a.scan());device.addView(scan);move(a.deviceList,device);Button query=k.button("刷新连接状态",false);query.setOnClickListener(v->a.query());device.addView(query);device.addView(k.copy("提醒和字幕需要保持 App 在前台。无需电脑或 USB；如连接失败，请检查手机网络和蓝牙。"));Button advanced=k.button("开发调试工具",false);advanced.setOnClickListener(v->debugHost.setVisibility(debugHost.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));if(BuildConfig.DEBUG)device.addView(advanced);debugHost.setVisibility(View.GONE);device.addView(debugHost);}
        if(!pages.containsKey(next))next="home";if(push&&!route.equals(next))back.push(route);route=next;if(isPrimary(next))tab=next;else if(Arrays.asList("communication","daily","danger","emotions","notifications").contains(next))tab="home";else if(Arrays.asList("voice","device").contains(next))tab="mine";else if(next.equals("detail"))tab="archives";islandWrap.setVisibility(View.VISIBLE);
        ((InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);root.clearFocus();
        for(Map.Entry<String,ScrollView> e:pages.entrySet())e.getValue().setVisibility(e.getKey().equals(next)?View.VISIBLE:View.GONE);
        header();String[] ids={"home","archives","marks","mine"};
        for(int n=0;n<4;n++){LinearLayout item=navItems.get(n);boolean on=tab.equals(ids[n]);item.setSelected(on);item.setBackground(k.touch(on?Color.WHITE:Color.TRANSPARENT,21));navigationIcons[n].filled(on);navigationIcons[n].color(on?k.ink:k.muted);k.press(item);navigationLabels[n].setTextColor(on?k.primary:k.muted);navigationLabels[n].setTypeface(null,on?Typeface.BOLD:Typeface.NORMAL);item.invalidate();}
        if(next.equals("archives"))renderArchives();if(next.equals("marks"))renderMarks();if(next.equals("emotions"))renderEmotions();if(next.equals("notifications"))renderNotifications();
    }
    void goBack(){if(route.equals("archives")&&!archiveCategory.isEmpty()){archiveCategory="";renderArchives();return;}if(!back.isEmpty())show(back.pop(),false);else if(!route.equals("home"))show("home",false);else a.moveTaskToBack(true);}
    void bind(AnalysisPanel analysis,DailyAlertPanel alerts,ReplyPanel replies,LinearLayout debug){
        move(analysis.dangerSection,dangerHost);move(analysis.emotionSection,emotionHost);move(analysis.connection,dangerHost);move(alerts.panel,dailyHost);move(replies.panel,replyHost);move(debug,debugHost);debug.setVisibility(View.VISIBLE);
        k.style(dangerHost);k.style(emotionHost);k.style(dailyHost);k.style(replyHost);k.style(debugHost);
        replies.styleCandidates(k);alerts.styleNative(k);analysis.styleNative(k);
        analysis.observer=this::onAnalysis;alerts.notice=(text)->feedback(text);
    }
    private void move(View view,LinearLayout into){if(view.getParent()!=null)((ViewGroup)view.getParent()).removeView(view);into.addView(view);}
    void onTranscript(JSONObject event){a.ui.post(()->{if(closed||!store.transcript(event))return;latestSid=event.optString("session_id");latestUid=event.optString("utterance_id");communicationCategory.setText(categoryNames[Arrays.asList(categoryIds).indexOf(store.category(latestSid))]);homeHeard.setText(event.optString("text"));inlineEmotion.setText(a.analysisPanel!=null&&!a.analysisPanel.isEmotionEnabled()?"情绪感知已关闭 · 可在记录本中开启":"情绪估计正在等待分析 · 说话人未确定");List<JSONObject> saved=store.rows("SELECT * FROM sentences WHERE sid=? AND uid=?",latestSid,latestUid);if(!saved.isEmpty()&&!saved.get(0).optString("emotion").isEmpty())inlineEmotion.setText(emotionLine(saved.get(0)));if(route.equals("archives"))renderArchives();});}
    private String emotionLine(JSONObject e){String emotion=e.optString("emotion"),tone=e.optString("tone");switch(emotion){case "neutral":emotion="平静 / 中性";break;case "happy":emotion="开心";break;case "sad":emotion="低落";break;case "angry":emotion="生气 / 急躁";break;case "unknown":emotion="无法确定";break;}return "情绪估计："+emotion+(tone.isEmpty()?"":"\n表达语气："+tone);}
    void onAnalysis(JSONObject e){
        if(closed)return;String type=e.optString("type");
        if(type.equals("emotion.estimate")){store.emotion(e);emotionSummary.setText("已有情绪记录，点此回看");if(e.optString("session_id").equals(latestSid)&&e.optString("utterance_id").equals(latestUid))inlineEmotion.setText(emotionLine(e));if(route.equals("emotions"))renderEmotions();}
        if(type.equals("emotion.unavailable")&&e.optString("session_id").equals(latestSid)&&e.optString("utterance_id").equals(latestUid))inlineEmotion.setText("这句话的情绪暂不可用");
        if(type.equals("danger.sound")||type.equals("danger.speech"))feedback("危险提醒 · "+(type.equals("danger.speech")?e.optString("text"):soundName(e.optString("sound"))),true);
    }
    private String soundName(String code){switch(code){case "car_horn":return "疑似汽车喇叭";case "siren":return "疑似警笛";case "scream":return "疑似呼救或尖叫";case "alarm":return "疑似警报";default:return "听到声音警示";}}
